1	/**
2	 * 赛狐 Temu 下架监测 CLI（挂在 temu-monitor 下）
3	 *
4	 *   node src/sellfox/cli.js init
5	 *   node src/sellfox/cli.js probe
6	 *   node src/sellfox/cli.js once | dry | start
7	 */
8	import { writeFileSync, existsSync, copyFileSync } from 'node:fs';
9	import {
10	  loadSellfoxConfig,
11	  sellfoxConfigReady,
12	  exampleConfigPath,
13	  configPath,
14	} from './config.js';
15	import { runSellfoxOnce, probeSellfox } from './monitor.js';
16	import { log } from '../logger.js';
17	
18	const cmd = process.argv[2] || 'once';
19	
20	function printHelp() {
21	  console.log(`
22	赛狐 OpenAPI · Temu 在售上下架监测（temu-monitor）
23	
24	命令:
25	  init     生成 sellfox.config.json（已存在则跳过）
26	  probe    只读探测：拉父体 + selectStatus 分布
27	  once     监测一轮（diff + 飞书 + 写快照）
28	  dry      一轮但不发飞书、不写快照
29	  start    按 intervalMinutes 常驻
30	  help     帮助
31	
32	配置: temu-monitor/sellfox.config.json（已 gitignore）
33	模板: temu-monitor/sellfox.config.example.json
34	
35	在售定义: selectStatus=12
36	  下架: 上轮在售、本轮不在（常见变为 13）
37	  上架: 本轮在售、上轮不在（新进 12，含重新上架）
38	限流/待关注: 赛狐无字段 → 继续用插件
39	alerts.delist / alerts.onshelf 默认 true，可单独关闭
40	`);
41	}
42	
43	async function cmdInit() {
44	  const dest = configPath();
45	  if (existsSync(dest)) {
46	    log.warn('已存在 sellfox.config.json，未覆盖。');
47	    return;
48	  }
49	  const ex = exampleConfigPath();
50	  if (existsSync(ex)) copyFileSync(ex, dest);
51	  else {
52	    writeFileSync(
53	      dest,
54	      JSON.stringify(
55	        {
56	          clientId: '',
57	          clientSecret: '',
58	          stores: [
59	            { shopId: '396706', name: 'Agnis', enabled: true },
60	            { shopId: '398202', name: 'HomeCove', enabled: true },
61	            { shopId: '398203', name: 'Twilight Cove', enabled: true },
62	          ],
63	        },
64	        null,
65	        2,
66	      ),
67	    );
68	  }
69	  log.info('已生成', dest);
70	  log.info('请填写 clientId/clientSecret（与 sellfox-bridge 相同即可）');
71	}
72	
73	async function cmdProbe() {
74	  const cfg = loadSellfoxConfig();
75	  const ready = sellfoxConfigReady(cfg);
76	  if (!ready.ok) {
77	    log.error(ready.reason);
78	    process.exitCode = 1;
79	    return;
80	  }
81	  const r = await probeSellfox(cfg);
82	  console.log(JSON.stringify(r, null, 2));
83	}
84	
85	async function cmdOnce(dry) {
86	  const cfg = loadSellfoxConfig();
87	  const ready = sellfoxConfigReady(cfg);
88	  if (!ready.ok) {
89	    log.error(ready.reason);
90	    log.info('先: node src/sellfox/cli.js init 并填写密钥');
91	    process.exitCode = 1;
92	    return;
93	  }
94	  const r = await runSellfoxOnce(cfg, { dryRun: !!dry });
95	  console.log(JSON.stringify(r, null, 2));
96	}
97	
98	async function cmdStart() {
99	  const cfg = loadSellfoxConfig();
100	  const ready = sellfoxConfigReady(cfg);
101	  if (!ready.ok) {
102	    log.error(ready.reason);
103	    process.exitCode = 1;
104	    return;
105	  }
106	
107	  // 可被 systemd SIGTERM / Ctrl+C 干净打断 sleep，避免强杀
108	  let stopping = false;
109	  let wake = null;
110	  const stop = (sig) => {
111	    if (stopping) return;
112	    stopping = true;
113	    log.info(`收到 ${sig}，本轮结束后退出…`);
114	    if (wake) wake();
115	  };
116	  process.on('SIGTERM', () => stop('SIGTERM'));
117	  process.on('SIGINT', () => stop('SIGINT'));
118	
119	  function interruptibleSleep(ms) {
120	    return new Promise((resolve) => {
121	      if (stopping) return resolve();
122	      const t = setTimeout(() => {
123	        wake = null;
124	        resolve();
125	      }, ms);
126	      wake = () => {
127	        clearTimeout(t);
128	        wake = null;
129	        resolve();
130	      };
131	    });
132	  }
133	
134	  log.info(`赛狐上下架监测常驻，间隔 ${cfg.intervalMinutes} 分钟。Ctrl+C / systemctl stop 退出。`);
135	  while (!stopping) {
136	    const t0 = Date.now();
137	    try {
138	      await runSellfoxOnce(cfg);
139	    } catch (e) {
140	      log.error('本轮失败：', e.message);
141	    }
142	    if (stopping) break;
143	    const waitMs = Math.max(60_000, cfg.intervalMinutes * 60_000 - (Date.now() - t0));
144	    log.info(`${Math.round(waitMs / 1000)} 秒后下一轮`);
145	    await interruptibleSleep(waitMs);
146	  }
147	  log.info('已退出常驻循环');
148	}
149	
150	async function main() {
151	  switch (cmd) {
152	    case 'help':
153	    case '-h':
154	    case '--help':
155	      printHelp();
156	      break;
157	    case 'init':
158	      await cmdInit();
159	      break;
160	    case 'probe':
161	      await cmdProbe();
162	      break;
163	    case 'once':
164	      await cmdOnce(false);
165	      break;
166	    case 'dry':
167	      await cmdOnce(true);
168	      break;
169	    case 'start':
170	      await cmdStart();
171	      break;
172	    default:
173	      log.error('未知命令：', cmd);
174	      printHelp();
175	      process.exitCode = 1;
176	  }
177	}
178	
179	main().catch((e) => {
180	  log.error(e);
181	  process.exitCode = 1;
182	});
183

