2	 * 赛狐监测配置
3	 * 文件：temu-monitor/sellfox.config.json（gitignore）
4	 * 可回落主 config.json.sellfox + 环境变量
5	 */
6	import { readFileSync, existsSync } from 'node:fs';
7	import { resolve } from 'node:path';
8	import { ROOT } from '../config.js';
9	
10	function readJson(path) {
11	  try {
12	    return JSON.parse(readFileSync(path, 'utf8'));
13	  } catch {
14	    return null;
15	  }
16	}
17	
18	export function configPath() {
19	  return resolve(ROOT, 'sellfox.config.json');
20	}
21	
22	export function exampleConfigPath() {
23	  return resolve(ROOT, 'sellfox.config.example.json');
24	}
25	
26	export function loadSellfoxConfig() {
27	  const main = readJson(resolve(ROOT, 'config.json')) || {};
28	  const local = readJson(configPath()) || {};
29	  const raw = { ...(main.sellfox || {}), ...local };
30	
31	  const clientId = String(raw.clientId || raw.client_id || process.env.SELLFOX_CLIENT_ID || '').trim();
32	  const clientSecret = String(raw.clientSecret || raw.client_secret || process.env.SELLFOX_CLIENT_SECRET || '').trim();
33	  const baseUrl = String(raw.baseUrl || raw.base_url || 'https://openapi.sellfox.com').replace(/\/$/, '');
34	
35	  const defaultShops = [
36	    { shopId: '396706', name: 'Agnis' },
37	    { shopId: '398202', name: 'HomeCove' },
38	    { shopId: '398203', name: 'Twilight Cove' },
39	  ];
40	
41	  let stores = Array.isArray(raw.stores) ? raw.stores : null;
42	  if (!stores || !stores.length) {
43	    const ids = raw.shopIds || raw.shop_whitelist || [];
44	    stores = (ids.length ? ids : defaultShops.map((s) => s.shopId)).map((id) => {
45	      const sid = String(id);
46	      const known = defaultShops.find((s) => s.shopId === sid);
47	      return { shopId: sid, name: known?.name || sid, enabled: true };
48	    });
49	  } else {
50	    stores = stores.map((s) => ({
51	      shopId: String(s.shopId || s.shop_id || ''),
52	      name: String(s.name || s.shopName || s.shopId || ''),
53	      enabled: s.enabled !== false,
54	    })).filter((s) => s.shopId);
55	  }
56	
57	  const hooks = [
58	    ...(Array.isArray(raw.feishuWebhooks) ? raw.feishuWebhooks : [raw.feishuWebhook]),
59	    ...(Array.isArray(main.feishuWebhooks) ? main.feishuWebhooks : [main.feishuWebhook]),
60	  ]
61	    .map((s) => String(s || '').trim())
62	    .filter(Boolean);
63	  const feishuWebhooks = [...new Set(hooks)];
64	
65	  return {
66	    enabled: raw.enabled !== false,
67	    clientId,
68	    clientSecret,
69	    baseUrl,
70	    stores,
71	    intervalMinutes: Number(raw.intervalMinutes || main.intervalMinutes) || 15,
72	    pageSize: Number(raw.pageSize) || 100,
73	    maxPagesPerWindow: Number(raw.maxPagesPerWindow) || 50,
74	    dateType: raw.dateType || 'updateDate',
75	    lookbackDays: Number(raw.lookbackDays) || 30,
76	    editBaseUrl: raw.editBaseUrl || 'https://agentseller.temu.com',
77	    debug: raw.debug === true || process.env.SELLFOX_DEBUG === '1',
78	    alerts: {
79	      delist: raw.alerts?.delist !== false,
80	      // 上架：本轮 selectStatus=12 且上轮不在在售集合
81	      onshelf: raw.alerts?.onshelf !== false,
82	    },
83	    feishuWebhooks,
84	    feishuSecret: raw.feishuSecret || main.feishuSecret || '',
85	    stateFile: resolve(ROOT, raw.stateFile || 'data/sellfox-state.json'),
86	  };
87	}
88	
89	export function sellfoxConfigReady(cfg) {
90	  if (!cfg) return { ok: false, reason: '无配置' };
91	  if (!cfg.clientId || !cfg.clientSecret) return { ok: false, reason: '缺少 clientId/clientSecret' };
92	  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
93	  if (!shops.length) return { ok: false, reason: '没有 enabled 的店铺 shopId' };
94	  return { ok: true, shops };
95	}
96	
97	export function shopNameMap(cfg) {
98	  const m = {};
99	  for (const s of cfg.stores || []) {
100	    if (s.shopId) m[s.shopId] = s.name || s.shopId;
101	  }
102	  return m;
103	}
104	
105	export function hasLocalConfig() {
106	  return existsSync(configPath());
107	}
