import { writeFileSync, readFileSync, unlinkSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { loadConfig, ROOT } from './config.js';
import { launchBrowser } from './browser.js';
import { calibrate } from './calibrate.js';
import { runOnce } from './run.js';
import { sendFeishu } from './feishu.js';
import { log } from './logger.js';

const cmd = process.argv[2] || 'once';
const cfg = loadConfig();
// 启动即告知日志路径（同事常以为没写文件，实际在 data/ 与 logs/）
log.announcePaths();

/** 常驻双开会抢 .userdata →「Target page/browser has been closed」。pid 锁防并行 start。 */
const START_LOCK = resolve(ROOT, 'data', 'start.lock');

/** @returns {{alive:boolean, pid?:number}} 是否有别的 start 进程持锁 */
function readStartLockHolder() {
  try {
    if (!existsSync(START_LOCK)) return { alive: false };
    const prev = Number(readFileSync(START_LOCK, 'utf8').trim());
    if (!prev || prev === process.pid) return { alive: false };
    try {
      process.kill(prev, 0); // 存在性探测
      return { alive: true, pid: prev };
    } catch {
      return { alive: false }; // stale
    }
  } catch {
    return { alive: false };
  }
}

function tryAcquireStartLock() {
  try {
    const holder = readStartLockHolder();
    if (holder.alive) return { ok: false, pid: holder.pid };
    writeFileSync(START_LOCK, String(process.pid), 'utf8');
    const release = () => { try { unlinkSync(START_LOCK); } catch {} };
    process.on('exit', release);
    process.on('SIGINT', () => { release(); process.exit(0); });
    process.on('SIGTERM', () => { release(); process.exit(0); });
    return { ok: true };
  } catch (e) {
    log.warn('start.lock 写入失败（忽略）：', e.message);
    return { ok: true };
  }
}

async function loginFlow() {
  // login 与 start 共用 .userdata：常驻在跑时再 login 会把监测的 Chrome 挤掉
  const holder = readStartLockHolder();
  if (holder.alive) {
    log.error(
      `检测到常驻监测正在运行（pid=${holder.pid}）。` +
        `请先关掉「流量常驻/守护」窗口，再点登录——否则会抢 .userdata，把正在扫的浏览器挤崩。`,
    );
    log.error(
      `若只是要进 Temu 后台人工操作：用你日常的 Chrome 打开即可，不必点本工具的「登录」。` +
        `本工具「登录」只给监测专用档案用。`,
    );
    process.exit(3);
  }
  log.info('打开浏览器，请在窗口中完成登录（手机号 + 密码，如需短信验证码请手动输入）。');
  log.info('注意：这是监测专用浏览器档案（.userdata），不是你日常 Chrome。');
  const { context, page } = await launchBrowser(cfg, { headless: false });
  await page.goto(cfg.loginUrl, { waitUntil: 'domcontentloaded' }).catch(() => {});
  log.info('等待登录完成…（最多 5 分钟）。登录并看到商品列表后即可，无需手动关闭窗口。');

  const deadline = Date.now() + 5 * 60 * 1000;
  let ok = false;
  while (Date.now() < deadline) {
    // 窗口被手动关闭则提前结束
    if (page.isClosed()) { log.warn('检测到浏览器窗口已关闭，结束等待。'); break; }
    try {
      await page.waitForTimeout(3000);
      const url = page.url();
      const loggedIn = await page
        .getByText(/商品列表|在售中|全部\s*\d+/)
        .first()
        .isVisible()
        .catch(() => false);
      if (loggedIn && !/login|signin/i.test(url)) { ok = true; break; }
    } catch (e) {
      // 登录页重定向/刷新期间的瞬时错误，忽略后继续轮询
      if (page.isClosed()) { log.warn('浏览器窗口已关闭，结束等待。'); break; }
      log.warn('轮询瞬时错误（忽略）：', e.message);
    }
  }
  if (ok) log.info('✅ 登录成功，session 已保存。之后可运行 npm run once / npm start。');
  else log.warn('⌛ 超时未检测到登录成功。若已登录可忽略；否则重试 npm run login。');
  await page.waitForTimeout(1500);
  await context.close().catch(() => {});
}

async function startLoop() {
  log.info(`常驻监测启动，间隔 ${cfg.intervalMinutes} 分钟。Ctrl+C 退出。`);
  let loginFailStreak = 0; // 连续「未登录」轮次
  let loginAlertedAt = 0;  // 上次就登录过期发告警时的连续轮次（0 = 尚未告警）

import { readFileSync, writeFileSync, existsSync, copyFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const ROOT = resolve(__dirname, '..');

/**
 * 确保有 config.json：缺失时从 config.example.json 自动复制（同事首次解压常见）。
 * @returns {string} 实际使用的配置路径
 */
export function ensureConfigFile() {
  const dest = resolve(ROOT, 'config.json');
  if (existsSync(dest)) return dest;
  const ex = resolve(ROOT, 'config.example.json');
  if (existsSync(ex)) {
    copyFileSync(ex, dest);
    console.warn(
      `[WARN] 未找到 config.json，已从 config.example.json 自动生成。\n` +
        `       请编辑 ${dest}\n` +
        `       - feishuWebhooks：自己的飞书机器人\n` +
        `       - storeList：要盯的店名\n` +
        `       - fullRun 保持 false\n`,
    );
    return dest;
  }
  // 最后兜底写一份最小配置，避免直接崩
  const minimal = {
    feishuWebhooks: [],
    intervalMinutes: 15,
    stores: 'all',
    storeList: ['Agnis', 'HomeCove', 'Twilight Cove'],
    fullRun: false,
    headless: true,
    proxy: '',
    userDataDir: './.userdata',
    channel: 'chrome',
  };
  writeFileSync(dest, JSON.stringify(minimal, null, 2), 'utf8');
  console.warn(`[WARN] 已写入最小 config.json：${dest}（请补飞书 webhook 与 storeList）`);
  return dest;
}

/** 读取并规范化 config.json */
export function loadConfig() {
  const path = ensureConfigFile();
  const raw = JSON.parse(readFileSync(path, 'utf8'));
  return {
    // 告警目标群 webhook：支持单个字符串或数组（多个群同发）。兼容旧字段 feishuWebhook。
    feishuWebhooks: (Array.isArray(raw.feishuWebhooks)
      ? raw.feishuWebhooks
      : [raw.feishuWebhooks ?? raw.feishuWebhook ?? ''])
      .map((s) => String(s || '').trim()).filter(Boolean),
    feishuSecret: raw.feishuSecret || '',
    intervalMinutes: Number(raw.intervalMinutes) || 15,
    stores: raw.stores || 'all',
    // 多店会话切店清单（店名与卖家中心顶栏英文名一致）。默认三店。
    storeList: Array.isArray(raw.storeList)
      ? raw.storeList
      : ['Agnis', 'HomeCove', 'Twilight Cove'],
    // 默认 false：本机只跑浏览器流量，不碰赛狐（避免同事电脑无白名单报错）。
    // 上下架请用服务器 `npm run sellfox:start`，或显式 fullRun:true / FULL_RUN=1 联调。
    fullRun: raw.fullRun === true || process.env.FULL_RUN === '1' || process.env.FULL_RUN === 'true',
    alerts: {
      onSaleDrop: raw.alerts?.onSaleDrop !== false,
      trafficAnomaly: raw.alerts?.trafficAnomaly !== false,
      // 赛狐下架 / 上架点名（fullRun 时启用，默认都开）
      delist: raw.alerts?.delist !== false,
      onshelf: raw.alerts?.onshelf !== false,
      // 登录过期/连续监测失败时发飞书提醒，避免登录态失效后静默死掉没人知道
      loginExpiry: raw.alerts?.loginExpiry !== false,
    },
    // 连续失败达到该轮次才发登录过期告警（默认 2 轮 ≈ 30 分钟，滤掉偶发抖动）
    loginAlertAfterRounds: Number(raw.loginAlertAfterRounds) || 2,
    // 仍未恢复时每隔多少轮再提醒一次（默认 16 轮 ≈ 4 小时，避免刷屏）
    loginRealertRounds: Number(raw.loginRealertRounds) || 16,
    headless: raw.headless === true,
    // 代理：config.proxy 若为字符串（含空串）则以它为准——空串 = 强制直连，
    // 不再回落系统 HTTPS_PROXY（实测本机 7897 代理会频繁 ERR_CONNECTION_CLOSED，直连反而稳）。
    // 仅当 config.json 完全没有 proxy 字段时才跟随系统环境变量。
    proxy: typeof raw.proxy === 'string' ? raw.proxy : (process.env.HTTPS_PROXY || process.env.HTTP_PROXY || ''),
    loginUrl: raw.loginUrl || 'https://agentseller.temu.com/goods/list',
    goodsListUrl: raw.goodsListUrl || 'https://agentseller.temu.com/goods/list',
    userDataDir: resolve(ROOT, raw.userDataDir || './.userdata'),
    // 浏览器 channel：默认 'chrome' = 用系统真实 Chrome（指纹与真人一致，最不易被风控识别）。
    // 设为 '' 或 'chromium' 则回落 Playwright 内置 Chromium。
    channel: raw.channel === '' ? '' : (raw.channel || 'chrome'),
    // 可选：显式指定 chrome.exe 路径，优先级高于 channel。
    executablePath: raw.executablePath || '',
    perStoreTimeoutMs: Number(raw.perStoreTimeoutMs) || 60000,
    navTimeoutMs: Number(raw.navTimeoutMs) || 60000,
  };
}

